  str_quest_base_story_new_chapter_open = "Chapter Quest baru kini tersedia",
  str_quest_base_daily_reset_tips = "Quest Harian telah direset",
  str_quest_base_awards_info_look = "Pratinjau Reward",
  str_quest_base_story_chapter_index = "Chapter %s",
  str_quest_base_story_all_chapter_clean = "Semua Chapter Quest selesai!",
  str_quest_base_story_current_chapter_clean = "Semua Quest dalam Chapter ini telah selesai",
  str_quest_base_story_click_lock_chapter = "Selesaikan quest di Plot sebelumnya untuk membuka",
  str_quest_base_desc_101 = "Soroz, ini awal perjalananmu. Hasil, perubahan, harapan, dan perkembangan tak terduga... Menjadi lebih kuat selalu diiringi penderitaan. Jika kamu tak bisa menghindarinya, terima saja. Penderitaanmu tak akan sia-sia.\n—Bethlehem",
  str_quest_base_desc_102 = "Tiba di dunia ini adalah pengalaman yang mendalam, bukan? Kuharap kamu bisa menghadapi krisis dengan tenang dan rasional, serta menghargai ikatanmu. Setiap orang dan segala sesuatu yang kamu lihat adalah bagian dari Astral, dan pada akhirnya akan menjadi bagian dari Aurora, bahkan bagian dari dirimu sendiri... Terima, pahami, tanggapi, dan teruslah berkembang.\n—Bethlehem",
  str_quest_base_desc_103 = "Gema dari masa lalu berkumandang lagi, dengan rekan senegara, musuh, dan saudara seperjuangan berdatangan. Bersiaplah menghadapi kemungkinan terburuk dan berharaplah yang terbaik. Timbanglah kebencian pribadimu dengan misi kelompok barumu. Pelajaran ini hanya bisa dipelajari lewat darah dan air mata.\n—Bethlehem",
  str_quest_base_desc_104 = "Sekarang, apa kamu sudah tahu tujuanmu? Apakah kamu merasa senasib dengan orang-orang di luar kelompokmu? Di sana ada kota Aurorian terakhir, sebuah pulau yang melayang di langit. Di sana, kamu akan menemukan persahabatan baru, dan mengambil langkah yang lebih teguh menuju perjalanan untuk mengatasi kegelapan.\n—Bethlehem",
  str_quest_base_desc_105 = "Terus gagal tetapi tetap berjuang, seperti binatang yang pantang menyerah, seperti pemberani yang memegang pedang tapi mati di negeri terlantar. Masa lalu akan terus maju, membuatmu berhadapan dengan ketakutan terbesarmu. Tatap wajahnya dan katakan kepadaku: Siapa yang kaulihat?\n—Bethlehem",
  str_quest_base_desc_106 = "Cemas? Seperti yang Aurora sarankan, kamu hampir di dasar, rawa penuh kepahitan dan kebencian, penjara besi yang dibangun dari kegagalan dan penghinaan. Namun, hanya di sini kamu bisa menemukan kekuatan sejati—bukan baja dan besi, melainkan visi yang luas dan pikiran yang inklusif.\n—Bethlehem",
  str_quest_base_desc_107 = "Akhirnya kita memasuki fase baru percakapan antarruang, Caelestite. Kamu tak akan pernah bisa paham peranku, sebagaimana aku tak paham potongan kata-kata yang ditulis sebagai pertanda yang samar. Aurora meredup, dan orang-orang putus asa dengan sayap terentang memenuhi langit Lumopolis. Kamu harus menaklukkannya, atau kamu akan ditaklukkan, itu saja.\n—Bethlehem",
  str_quest_base_desc_108 = "Bahkan di jurang terdalam dan tergelap, Anda akan bertahan untuk melihat penggenapan ramalan itu. Itulah yang saya yakini, dan intuisi saya bersikeras untuk saya ikuti. Raih kesempatan ini, Caelestite, dan kutuk benteng hitam kembali ke tempatnya semula!\n—Bethlehem",
  str_quest_base_desc_109 = "Kita memiliki dua rumah: Rumah di bawah kakimu, dan rumah di dalam hatimu. Yang beruntung di antara kita akan menyadari bahwa tidak ada perbedaan di antara keduanya. Namun, kebanyakan jiwa harus bertahan dari perseteruan tiada henti di antara keduanya, dan bahkan dibiarkan tanpa asa untuk sekali lagi menjejakkan kakinya di negeri yang jauh di dalam ingatan. Meski hati merasa enggan, tiada cara lain selain meninggalkan.\n                                                                                                                       —Bethlehem",
  str_quest_base_desc_110 = "Aku yakin negeri itu akan mendukungmu untuk tumbuh, mengingatkanmu akan banyak hal, sembari memungkinkanmu berdamai dengan tenang dengan mereka. Akhir perjalanan kita telah menanti. Singkirkan rasa benci dan dendammu, biarkan ia menghilang. Kuharap kali lain kita bertemu, kau telah menjadi diri yang baru.\n                                                                                                                       —Bethlehem",
  str_quest_base_desc_111 = [[
Eternal Night, tanah yang tak akan dipijak oleh Aurorian mana pun, merupakan jurang yang diselimuti kegelapan. Selama Twilight Interlude ini, ambillah kesempatan terkecil yang ada untuk menembus kegelapan, master Colossus. Semoga harapanmu terkabul.

-- Bethlehem]],
  str_quest_base_desc_112 = "Harapan sering kali disertai dengan cobaan, bagaikan sekuntum bunga yang dipenuhi duri. Jika kau siap babak belur, kembalilah ke tempat awal mulamu. Untuk mencari, kehilangan, putus asa, dan akhirnya, menengadahkan kepalamu sekali lagi.\n\n—Bethlehem",
  str_quest_base_desc_113 = "Belati kebenaran menembus dada seseorang, mengoyak hatinya yang rapuh hingga tak bersisa. \"Bagaimana bisa?\" \"Tidak mungkin!\"\nTerperanjat, bimbang, benci, lalu menatap kehampaan di tepi jurang kehilangan. Aku tak bisa melihat pilihanmu, Caelestite. Aku tak bisa melihat apa pun.\n\n——Bethlehem",
  str_quest_base_desc_114 = "Setiap orang terus menerus mencari ilmu dalam hidupnya. Anda beruntung, namun juga menyedihkan. Nasib memberi Anda lebih banyak ruang untuk dijelajahi. Anda bisa melangkah lebih jauh dari kebanyakan orang, tetapi ini adalah perjalanan yang sepi. Saya tidak tahu di mana Anda akan berakhir, karena tujuan Anda terletak di luar apa yang dapat saya lihat.\n—Betlehem",
  str_quest_base_desc_115 = "Pernahkah Anda memperhatikan bahwa Anda mulai bertemu lebih banyak orang? Mereka memiliki asal dan tujuan yang berbeda, namun jalur mereka bertepatan dengan jalur Anda pada titik tertentu. Begitu banyak orang hidup di bawah langit. Yang beruntung dengan matahari di atas kepalanya bermandikan sinar matahari yang paling melimpah, tetapi mereka yang berdiri di senja adalah yang terjauh dari matahari.\n—Betlehem",
  str_quest_base_desc_116 = "Betapa ironisnya nasib yang memaksa Anda untuk bersama dengan musuh lama. Apakah lautan api atau lubang yang dalam ada di depan, tidak ada pilihan selain menghadapinya dengan teman-teman Anda.\n—Bethlehem",
  str_quest_base_desc_117 = "Medan perang adalah panggung bagi perencana, dan penonton yang bodoh berduyun-duyun ke sana dari segala arah. Malam tanpa batas semakin dekat, namun Aurorian belum terbangun dari mimpi indah mereka.\n—Bethlehem",
  str_quest_base_desc_118 = "Di tengah perubahan kekuasaan, mereka yang terabaikan oleh takdir bangkit ke panggung dunia di bawah pandangan banyak orang. Namun, ambisi terbukti menjadi senjata paling sia-sia di medan perang: hanya dengan mengalahkan diri sendiri yang dulu, seseorang dapat lepas dari pusaran politik dan memperoleh kehidupan yang diperbaharui.\n—Bethlehem",
  str_quest_base_desc_119 = "Apakah kekuatan berasal dari dorongan diri atau pemberian orang lain? Hingga kamu menyaksikan bentuk yang perkasa berjuang dalam lumpur, menggali kuburan mereka sendiri, kamu akan akhirnya menyadari bahwa kerapuhan adalah inti dari kehidupan.\n—Bethlehem",
  str_quest_base_desc_120 = "Sebuah keberadaan asing akhirnya membuat kontak dengan Illumina setelah lebih dari 600 tahun. Haruskah kita membalik halaman buku sejarah untuk mencari kemungkinan, atau harus kita meninggalkan masa lalu dan membentuk jalan baru? Itulah pertanyaan yang ada, serta teka-teki yang telah mengganggu banyak generasi Aurorian.\n—Bethlehem",
  str_quest_base_desc_121 = "Kamu telah menghabiskan berjam-jam kebahagiaan bersama teman-temanmu, tetapi kamu tidak pernah berpikir bahwa waktu untuk mengucapkan selamat tinggal akan datang begitu cepat. Sinyal dari masa lalu telah kembali. Kali ini, kamu harus menjadi kuat dan menjelajahi masa lalumu di reruntuhan yang tidak diketahui.\n—Bethlehem",
  str_quest_base_desc_122 = "\"Untuk mendirikan mercusuar di sepanjang jalan di depan,\" demikianlah aku, Queen dari Utara berbicara.\n—Bethlehem",
  str_quest_base_type_stroy_with_space = "Story",
