  str_quest_base_achieve_type_200_space = "Petualangan",
  str_quest_base_achieve_type_407_space = "Colossus",
  str_quest_base_achieve_finish_list_title = "Quest Selesai",
  str_quest_base_desc_123 = "Kamu telah menyaksikan malam yang abadi—apakah kamu telah memantapkan tekad di hatimu? Tak terhitung jiwa terjebak dalam kebuntuan bayangan, mengejar harapan yang sekejap. Tapi untukmu, harapan itu nyata.\nKamu akan meraihnya, karena cerita ini dimulai dengan langkah pertamamu sebagai seorang pahlawan. Kamu akan menjaga percikan harapan itu, dan sebagai balasannya, itu akan bertahan karena dirimu. Percayalah pada ini, dan maju dengan iman yang tak tergoyahkan.\n—Bethlehem",
